  `b_tinggal_dengan_nama` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Tinggal Sama Siapa?',
  `b_jarak_dari_rumah` int NULL DEFAULT NULL COMMENT '0 = 0 - 2 km, 1 = 2-5 km, 2 = Lebih dari 5 km',
  `b_transportasi_ke_sekolah` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Misalkan Naik Mobil,Motor,Sepeda, Angkot dll',
  `b_status_rumah` int NULL DEFAULT NULL COMMENT '0 = Kontrak/Sewa, 1 = Milik Sendiri/Keluarga, 2 = Dinas, 3 = Lainnya, Sebutkan',
  `b_status_rumah_nama` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Rumah Milik Siapa?',
  `b_kondisi_rumah` int NULL DEFAULT NULL COMMENT '0 = Padat Penduduk, 1 = Sedang, 3 = Perumahan',
  `c_telp_ayah` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nomor Telp Ayah',
  `c_gaji_ayah` double(19, 2) NULL DEFAULT NULL COMMENT 'Gaji Ayah',
  `c_telp_ibu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nomor Telp Ibu',
  `c_gaji_ibu` double(19, 2) NULL DEFAULT NULL COMMENT 'Gaji Ibu',
  `c_nama_kontak_darurat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nama Kontak Darurat Yang Bisa Dihubungi',
  `c_nomor_kontak_darurat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nomor Kontak Darurat Yang Bisa DIhubungi',
  `d_memiliki_penyakit` int NULL DEFAULT NULL COMMENT '0 = Ya, 1 = Tidak',
  `d_jenis_penyakit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Contoh Asma , Jantung, Ginjal dll',
  `d_kategori_penyakit` int NULL DEFAULT NULL COMMENT '0 = Berat/Akut, 1 = Sedang, 2 = Ringan',
  `e_alasan_mendaftar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Mengapa mendaftar disekolah ini ?',
  `e_mendaftar_disekolah_lain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apakah kamu juga mendaftar disekolah lain?',
  `e_dukungan_orangtua` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apakah orang tua kamu mendukung untuk bersekolah disini?',
  `e_info_tentang_sekolah` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Dari mana kamu mengetahui sekolah ini?',
  `e_citacita_siswa` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apa cita-cita kamu sekarang?',
  `e_kelebihan_siswa` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apakah kelebihan yang ada pada dirimu?',
  `e_kekurangan_siswa` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apakah kekurangan yang ada pada dirimu?',
  `e_rencana_mutasi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Apakah ada rencana untuk mutasi kesekolah lain?',
  `e_nama_instagram` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nama Instagram',
  `e_gmail_aktif` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Gmail Aktif',
  `f_prestasi_akademis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Prestasi Akademis',
  `f_prestasi_non_akademis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Prestasi Non Akademis',
  `g_nilai_ipa` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nilai IPA',
  `g_nilai_ips` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nilai IPS',
  `g_nilai_mtk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nilai Matematika',
  `g_nilai_bahasa_indonesia` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Nilai Bahasa Indonesia',
  `h_bidang_akademis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Bidang Akademis',
  `h_bidang_olahraga` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Bidang Olahraga',
  `h_bidang_kesenian` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Bidang Kesenian',
  `h_hobi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Hobi',
  `h_ekstrakurikuler` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Ekstrakulikuler',
  `i_penerima_kjp` int NULL DEFAULT NULL COMMENT '0 = Ya, 1 = Tidak',
  `j_catatan_umum_wawancara` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Catatan Umum Wawancara',
  `j_catatan_khusus_wawancara` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Catatan Khusus Wawancara',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1246 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

