DROP VIEW IF EXISTS `vw_group_uang_keluar`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_group_uang_keluar` AS select sum(`b`.`jml_bayar`) AS `total_bayar`,`b`.`kd_post_uang_masuk` AS `kd_group`,`c`.`nm_group` AS `nm_group` from ((`tbl_trans_uang_keluar_pra_act_headers` `a` join `tbl_trans_uang_keluar_pra_act_details` `b` on(`a`.`kd_trans_keluar` = `b`.`kd_trans_keluar`)) join `tbl_group_kategoris` `c` on(`a`.`kd_group` = `c`.`kd_group`)) where `a`.`flag_aktif` = 0 and `b`.`flag_aktif` = 0 and `c`.`flag_aktif` = 0 and `b`.`kd_post_uang_masuk` is not null group by `b`.`kd_post_uang_masuk`,`b`.`kd_trans_keluar_detail` union all select sum(`b`.`jml_bayar`) AS `total_bayar`,`b`.`kd_post_uang_masuk` AS `kd_group`,`c`.`nm_group` AS `nm_group` from ((`tbl_trans_uang_keluar_act_headers` `a` join `tbl_trans_uang_keluar_act_details` `b` on(`a`.`kd_trans_keluar` = `b`.`kd_trans_keluar`)) join `tbl_group_kategoris` `c` on(`a`.`kd_group` = `c`.`kd_group`)) where `a`.`flag_aktif` = 0 and `b`.`flag_aktif` = 0 and `c`.`flag_aktif` = 0 and `b`.`kd_post_uang_masuk` is not null group by `b`.`kd_post_uang_masuk`,`b`.`kd_trans_keluar_detail`; ;

