WHERE
  `vw_report_spp`.`tgl_bayar` IS NOT NULL 
  AND `vw_report_spp`.`jml_bayar` IS NOT NULL 
GROUP BY
  `vw_report_spp`.`kd_trans_masuk_detail` UNION ALL
SELECT
  `vw_report_umsiswa`.`nm_group` AS `nm_group`,
  `vw_report_umsiswa`.`nm_kategori` AS `nm_kategori`,
  `vw_report_umsiswa`.`tgl_bayar` AS `tgl_bayar`,
  `vw_report_umsiswa`.`total_bayar` AS `total_bayar`,
  `vw_report_umsiswa`.`kd_kategori` AS `kd_kategori`,
  `vw_report_umsiswa`.`jml_bayar` AS `jml_bayar`,
  `vw_report_umsiswa`.`tipe_pembayaran` AS `tipe_pembayaran`,
  `vw_report_umsiswa`.`kd_group` AS `kd_group`,
  `vw_report_umsiswa`.`nis_siswa` AS `nis_siswa`,
  `vw_report_umsiswa`.`nm_siswa` AS `nm_siswa` ,
   `vw_report_umsiswa`.`keterangan_detail` AS `keterangan`
FROM
  `vw_report_umsiswa` 
WHERE
  `vw_report_umsiswa`.`tgl_bayar` IS NOT NULL 
  AND `vw_report_umsiswa`.`jml_bayar` IS NOT NULL 
GROUP BY
  `vw_report_umsiswa`.`kd_trans_masuk_detail_siswa` UNION ALL
SELECT
  `vw_report_umlain`.`nm_group` AS `nm_group`,
  `vw_report_umlain`.`nm_kategori` AS `nm_kategori`,
  `vw_report_umlain`.`tgl_bayar` AS `tgl_bayar`,
  `vw_report_umlain`.`total_bayar` AS `total_bayar`,
  `vw_report_umlain`.`kd_kategori` AS `kd_kategori`,
  `vw_report_umlain`.`jml_bayar` AS `jml_bayar`,
  `vw_report_umlain`.`tipe_pembayaran` AS `tipe_pembayaran`,
  `vw_report_umlain`.`kd_group` AS `kd_group`,
  `vw_report_umlain`.`no_document` AS `no_document`,
  `vw_report_umlain`.`keterangan` AS `keterangan_header`,
  `vw_report_umlain`.`keterangan_detail` AS `keterangan`  
FROM
  `vw_report_umlain` 
WHERE
  `vw_report_umlain`.`tgl_bayar` IS NOT NULL 
  AND `vw_report_umlain`.`jml_bayar` IS NOT NULL 
GROUP BY
  `vw_report_umlain`.`kd_trans_masuk_detail_lain` ;

SET FOREIGN_KEY_CHECKS = 1;
